let contextPin = '';
let deliveryAction = '';
const event = $('Only useful messages').first().json;
const msg = event.message || {};
const fromUser = msg.from || {};
if (fromUser.is_bot) {
  return [];
}
let text = msg.text ? String(msg.text).trim() : '';
if (!text && msg.caption) text = String(msg.caption).trim();
const hasPhoto = Array.isArray(msg.photo) && msg.photo.length > 0;
const hasDocument = !!(msg.document && msg.document.file_id);
if (!text && !hasPhoto && !hasDocument) {
  return [];
}
const chat = msg.chat || {};
const chatId = String(chat.id || '');
const chatKind = (chat.type === 'group' || chat.type === 'supergroup') ? 'group' : 'dm';
const telegramId = String(fromUser.id || '');

function loadStaff() {
  try {
    const s = $('Fetch staff').first().json || {};
    if (s && s.known) return s;
  } catch (e) {}
  return { known: false, telegram_id: telegramId, prefixes: [], can_approve: false, default_dept: '', user: {} };
}
const staff = loadStaff();
const idLine = 'Your Telegram id is ' + telegramId + '. Paste it on People.';

if (chatKind === 'group') {
  return [{ json: { skip_llm: true, chat_id: chatId, text: 'This office bot is 1:1. Student rooms use the Academy bot.' } }];
}

if (!staff.known) {
  return [{ json: { skip_llm: true, chat_id: chatId, text: 'This bot is the office. ' + idLine } }];
}

const who = String((staff.user && staff.user.name) || 'you');
const role = String((staff.user && staff.user.role) || '');
const prefixes = Array.isArray(staff.prefixes) ? staff.prefixes.map(String) : [];
const office = !!(staff.user && staff.user.office);

function mayPrefix(cmd) {
  cmd = String(cmd || '').toLowerCase();
  return prefixes.some((p) => String(p).toLowerCase().split(/\s+/)[0] === cmd);
}

const prefixOf = {
  community: '/cm',
  accounts: '/accounts',
  'internal-ops': '/ops',
  'product-dev': '/validate',
  growth: '/growth',
  crm: '/crm',
  legal: '/legal',
  seo: '/seo',
  delivery: '/today',
  hr: '/hr',
  files: '/file'
};

function mayDept(dept) {
  if (office) return true;
  const p = prefixOf[dept];
  if (!p) return false;
  return mayPrefix(p);
}

function helpText() {
  const lines = [
    'Office bot for ' + who + ' (' + role + ').',
    idLine,
    'You may use: ' + (prefixes.join(', ') || 'nothing until a desk is ticked on People.')
  ];
  if (staff.can_approve) {
    lines.push('/approve sends the pending info@ draft now. /stop or /kill drops it.');
  }
  lines.push('No prefix uses ' + (staff.default_dept || 'ops') + '. WhatsApp is for customers.');
  return lines.join('\n');
}

if (/^\/(start|help)(?:@\w+)?\b/i.test(text)) {
  return [{ json: { skip_llm: true, chat_id: chatId, text: helpText() } }];
}

if (/^\/approve(?:@\w+)?\b/i.test(text)) {
  if (!staff.can_approve) {
    return [{ json: { skip_llm: true, chat_id: chatId, text: 'Only owner and BDM send the pending info@ draft.' } }];
  }
  return [{ json: { skip_llm: true, ops_action: 'approve', chat_id: chatId, text: '' } }];
}
if (/^\/(?:kill|stop)(?:@\w+)?\b/i.test(text)) {
  if (!staff.can_approve) {
    return [{ json: { skip_llm: true, chat_id: chatId, text: 'Only owner and BDM drop the pending info@ draft.' } }];
  }
  return [{ json: { skip_llm: true, ops_action: 'kill', chat_id: chatId, text: '' } }];
}

let department = staff.default_dept || 'internal-ops';
const commands = [
  { re: /^(?:\/community|\/cm)(?:@\w+)?\b\s*/i, dest: 'community', prefix: '/cm' },
  { re: /^\/accounts(?:@\w+)?\b\s*/i, dest: 'accounts', prefix: '/accounts' },
  { re: /^\/ops(?:@\w+)?\b\s*/i, dest: 'internal-ops', prefix: '/ops' },
  { re: /^\/validate(?:@\w+)?\b\s*/i, dest: 'product-dev', prefix: '/validate' },
  { re: /^\/growth(?:@\w+)?\b\s*/i, dest: 'growth', prefix: '/growth' },
  { re: /^\/crm(?:@\w+)?\b\s*/i, dest: 'crm', prefix: '/crm' },
  { re: /^\/legal(?:@\w+)?\b\s*/i, dest: 'legal', prefix: '/legal' },
  { re: /^\/seo(?:@\w+)?\b\s*/i, dest: 'seo', prefix: '/seo' },
  { re: /^(?:\/today|\/pm)(?:@\w+)?\b\s*/i, dest: 'delivery', action: 'today', prefix: '/today' },
  { re: /^\/idea(?:@\w+)?\b\s*/i, dest: 'delivery', action: 'idea', prefix: '/today' },
  { re: /^\/hr(?:@\w+)?\b\s*/i, dest: 'hr', prefix: '/hr' },
  { re: /^\/file(?:@\w+)?\b\s*/i, dest: 'files', prefix: '/file' }
];
let usedPrefix = '';
for (const cmd of commands) {
  if (cmd.re.test(text)) {
    department = cmd.dest;
    usedPrefix = cmd.prefix;
    if (department === 'delivery') {
      deliveryAction = cmd.action || 'today';
      const m = String(text || '').match(/^\S+\s+([a-z0-9-]{2,32})\b/i);
      if (m) contextPin = m[1].toLowerCase();
    }
    text = text.replace(cmd.re, '').trim();
    break;
  }
}

if (hasDocument && (department === 'growth' || department === 'community' || department === 'internal-ops' || !usedPrefix) && mayDept('files')) {
  department = 'files';
}
if (hasPhoto && !hasDocument && (department === 'growth' || department === 'internal-ops' || !usedPrefix) && mayDept('accounts')) {
  department = 'accounts';
}

if (!mayDept(department)) {
  return [{ json: { skip_llm: true, chat_id: chatId, text: 'That desk is not on your People card. You may use: ' + (prefixes.join(', ') || 'nothing yet.') } }];
}

let photo_file_id = '';
if (hasPhoto) {
  const last = msg.photo[msg.photo.length - 1] || {};
  photo_file_id = String(last.file_id || '');
}
let document_file_id = '';
let filename = '';
let file_mime = '';
if (hasDocument) {
  document_file_id = String(msg.document.file_id || '');
  filename = String(msg.document.file_name || '');
  file_mime = String(msg.document.mime_type || '');
}
if (hasDocument && !text) {
  text = 'Classify this file into a project directory and subdirectory from the catalog. Do not invent a folder. Do not write Drive.';
} else if (hasPhoto && !text) {
  text = 'Read this receipt or invoice photo. Extract vendor or customer, amount, currency, date, and whether it is already paid. If the image is unreadable, ask for those fields and set zoho_action to none. Do not invent figures.';
} else if (!text) {
  text = department === 'community'
    ? 'Welcome this person and ask how you can help in the community.'
    : 'Greet the person and ask how you can help.';
}
let recent_messages = [];
try {
  const store = $getWorkflowStaticData('global');
  const histKey = 'legal_thread_' + chatId;
  recent_messages = Array.isArray(store[histKey]) ? store[histKey].slice() : [];
  const line = String(text || '').slice(0, 400);
  if (line) {
    recent_messages.push(line);
    if (recent_messages.length > 8) recent_messages = recent_messages.slice(-8);
    store[histKey] = recent_messages;
  }
} catch (e) {}
const actor = staff.user || {};
return [{
  json: {
    skip_llm: false,
    department,
    task_description: text,
    context_data: {
      channel: 'telegram',
      chat_kind: chatKind,
      department,
      chat_id: chatId,
      from: telegramId,
      username: fromUser.username || '',
      actor_id: actor.id || undefined,
      actor_name: actor.name || '',
      actor_role: actor.role || '',
      photo_file_id,
      document_file_id,
      telegram_file_id: document_file_id || photo_file_id,
      filename,
      file_mime,
      caption: msg.caption ? String(msg.caption).trim() : '',
      recent_messages,
      project_slug: contextPin || undefined,
      action: department === 'delivery' ? (deliveryAction || 'today') : undefined
    }
  }
}];

const worker = $('Call department').item.json;
const ctx = $('Prepare task').item.json.context_data;
let text = String(worker.output_text || 'Sorry, I could not complete that.');
text = text.replace(/^#{1,6}\s+/gm, '').replace(/\*\*/g, '').replace(/\*/g, '').trim();
if (String(ctx.department || '') === 'legal') {
  text += '\n\nProposal only. File and Accept on the company desk. This chat cannot send or stamp.';
}
if (String(ctx.department || '') === 'seo') {
  text += '\n\nProposal only. Accept on the SEO book. This chat cannot publish the live page.';
}
if (String(ctx.department || '') === 'files') {
  text += '\n\nCatalog match files itself. Odd paths stay on Files for Accept. This chat cannot write Drive.';
}
if (String(ctx.department || '') === 'delivery') {
  text += '\n\nCheck-ins on your own tasks apply now. New plans write after a delay unless you Turn away. Extra work sits on Backlog. /approve is still only the info@ draft.';
}
let legalNote = '';
try {
  if (String(ctx.department || '') !== 'legal') {
    const watch = $('Watch legal').first().json || {};
    const wsd = watch.structured_data || {};
    const speak = wsd.speak === true || wsd.speak === 'true';
    const wtext = String(watch.output_text || '').trim();
    if (speak && wtext) {
      const sev = String(wsd.severity || 'note');
      const label = sev === 'stop' ? 'Legal · stop' : (sev === 'caution' ? 'Legal · caution' : 'Legal');
      legalNote = '\n\n' + label + '\n' + wtext;
    }
  }
} catch (e) {}
let zohoNote = '';
if ($json.audit_text) {
  zohoNote = '\n\n' + String($json.audit_text);
} else if ($json.expense && $json.expense.expense_id) {
  zohoNote = '\n\nRecorded in Zoho Books as expense ' + $json.expense.expense_id + '.';
} else if ($json.bill && $json.bill.bill_id) {
  zohoNote = '\n\nRecorded in Zoho Books as bill ' + $json.bill.bill_id + '.';
} else if ($json.invoice && $json.invoice.invoice_id) {
  zohoNote = '\n\nDraft invoice in Zoho Books ' + ($json.invoice.invoice_number || $json.invoice.invoice_id) + '.';
} else if ($json.code && $json.message) {
  zohoNote = '\n\nZoho Books: ' + String($json.message);
} else if ($json.error) {
  const err = $json.error;
  zohoNote = '\n\nZoho Books: ' + String(err.message || JSON.stringify(err));
}
try {
  const c = $('Run CRM upsert').first().json || {};
  const id = (c.contact && c.contact.contact_id) || c.contact_id;
  if (id) zohoNote += '\n\nCRM: Zoho Books contact ' + id;
  else if (c.message && c.code) zohoNote += '\n\nCRM: ' + c.message;
} catch (e) {}
text = (text + legalNote + zohoNote).trim();
if (text.length > 4000) {
  text = text.slice(0, 3990) + '…';
}
return [{
  json: {
    chat_id: ctx.chat_id,
    text,
    status: worker.status || 'failed',
    department: ctx.department || 'growth'
  }
}];

const worker = $('Call department').item.json;
const prep = $('Prepare task').item.json;
const sd = worker.structured_data || {};
const task = String(sd.task_type || '').toLowerCase();
const accountsDept = prep.department === 'internal-ops' || prep.department === 'accounts';
let action = String(sd.zoho_action || '').toLowerCase();
const allowed = ['expense', 'bill', 'invoice', 'lookup', 'preview'];
if (!allowed.includes(action) && (sd.record_expense === true || sd.record_expense === 'true')) {
  action = 'expense';
}
const record_zoho = accountsDept
  && worker.status === 'success'
  && task === 'accounts'
  && allowed.includes(action);

return [{ json: {
  ...worker,
  ...sd,
  record_zoho,
  action: record_zoho ? action : 'none',
  amount: sd.amount,
  vendor_name: sd.vendor_name || sd.vendor || '',
  customer_name: sd.customer_name || '',
  date: sd.date,
  description: String(sd.notes || prep.task_description || '').slice(0, 200),
  zoho_account_name: sd.zoho_account_name,
  is_taxable_service: sd.is_taxable_service === true,
  is_professional_service: sd.is_professional_service === true,
  reference: sd.reference || sd.reference_number || '',
  lookup: sd.lookup || 'overview',
  currency: sd.currency || 'NGN'
} }];

const j = $input.first().json;
const chat_id = String(j.chat_id || (j.context_data && j.context_data.chat_id) || '');
const known = !!(j.context_data && (j.context_data.actor_id || j.context_data.actor_name));
if (j.skip_llm && !j.ops_action && !known) {
  return [{ json: { ...j, action: 'skip', chat_id } }];
}
return [{ json: { ...j, action: 'set_chat', chat_id } }];

const r = $input.first().json || {};
const prep = $('Prepare task').item.json;
const chat_id = String(prep.chat_id || (prep.context_data && prep.context_data.chat_id) || '');
let text = String(r.text || '').trim();
if (r.sent) text = 'Sent to ' + (r.to || 'the sender') + '.';
else if (r.killed) text = 'Dropped the pending draft.';
else if (r.empty) text = 'No pending email draft.';
if (!text) text = 'No pending email draft.';
return [{ json: { chat_id, text } }];

const worker = $('Call department').item.json;
const prep = $('Prepare task').item.json;
const sd = worker.structured_data || {};
const ctx = prep.context_data || {};
const task = String(sd.task_type || '').toLowerCase();
const intent = Number(sd.intent_score);
const recordFlag = sd.record_lead === true || sd.record_lead === 'true';
const deskOnly = prep.department === 'legal' || prep.department === 'seo' || prep.department === 'delivery' || prep.department === 'hr';
const record_crm = worker.status === 'success' && !deskOnly && (
  prep.department === 'crm' ||
  recordFlag ||
  (Number.isFinite(intent) && intent >= 0.6)
);
let phone = String(sd.phone || '').trim();
if (!phone && ctx.channel === 'whatsapp' && ctx.from && /^\d{8,}$/.test(String(ctx.from))) {
  phone = String(ctx.from);
}
let email = String(sd.email || '').trim();
if (!email && ctx.channel === 'email' && ctx.from && String(ctx.from).includes('@')) {
  email = String(ctx.from);
}
let contact_name = String(sd.contact_name || sd.name || '').trim();
if (!contact_name && ctx.username) contact_name = String(ctx.username);
const crm_contact = record_crm ? {
  contact_name,
  company_name: String(sd.company_name || '').trim(),
  email,
  phone,
  pipeline_stage: String(sd.pipeline_stage || 'new'),
  next_action: String(sd.next_action || '').trim(),
  notes: String(sd.notes || '').trim(),
  source: ctx.channel || 'ops',
  task_type: task
} : null;
return [{ json: { ...worker, record_crm, crm_contact } }];

const prep = $('Prepare task').first().json;
const ctx = Object.assign({}, prep.context_data || {});
const item = $input.first();
const bins = item.binary || {};
const key = Object.keys(bins)[0];
if (key && bins[key] && bins[key].data) {
  const mime = bins[key].mimeType || ctx.file_mime || ctx.image_mime || 'application/octet-stream';
  const isDoc = !!ctx.document_file_id || (mime && mime.indexOf('image/') !== 0);
  if (isDoc) {
    ctx.has_file = true;
    ctx.file_mime = mime;
    ctx.file_base64 = bins[key].data;
    if (bins[key].fileName && !ctx.filename) ctx.filename = bins[key].fileName;
  } else {
    ctx.has_image = true;
    ctx.image_mime = mime;
    ctx.image_base64 = bins[key].data;
  }
  ctx.telegram_file_id = ctx.document_file_id || ctx.photo_file_id || '';
}
if (prep.department !== 'files') {
  delete ctx.photo_file_id;
}
return [{ json: { ...prep, context_data: ctx } }];

const event = $input.first().json;
const id = String((((event.message || {}).from) || {}).id || '');
return [{ json: { telegram_id: id } }];
